class Solution:
    def findDuplicate(self, nums: list[int]) -> int:
        # 阶段一：找到快慢指针在环内的相遇点
        slow = nums[0]
        fast = nums[0]
        while True:
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break

        # 阶段二：找到环的入口
        slow = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]

        return slow
